// Se junta lo que dice la base (quien esta callado) con lo que dice Evolution
// (que instancias estan conectadas). Son preguntas distintas y una no cubre a
// la otra: el trafico de los agentes VIEJOS no pasa por la plataforma, asi que
// esos clientes SOLO se ven por Evolution. Es el caso de FerreteriaYa.

// OJO: `.all()` y no `.first()`. El nodo de HTTP devuelve UN ITEM POR
// INSTANCIA, asi que leer solo el primero devolvia una instancia suelta, el
// filtro no encontraba nada y el vigilante decia que todo estaba bien —
// teniendo cuatro instancias caidas hace 18 dias. Fallar en silencio es
// justo lo que este flujo existe para evitar.
const salud = $('Como va cada empresa').all().map((x) => x.json);

let inst = [];
try {
  const items = $('Instancias de WhatsApp').all().map((x) => x.json);
  for (const it of items) {
    if (Array.isArray(it)) inst = inst.concat(it);
    else if (Array.isArray(it.data)) inst = inst.concat(it.data);
    else if (it && (it.name || it.instanceName)) inst.push(it);
  }
} catch (e) { inst = []; }

// Evolution repite cada instancia, asi que se deja una por nombre.
const vistas = {};
for (const i of inst) {
  const n = i.name || i.instanceName || 'sin nombre';
  if (!vistas[n]) vistas[n] = i;
}

// `open` es conectada. `connecting` NO lo es: es justo el estado en el que se
// quedaron las cuatro de FerreteriaYa el 23 de agosto, y en el que llevan
// desde entonces sin que nadie se enterara.
const desconectadas = Object.keys(vistas).map((n) => {
  const e = String(vistas[n].connectionStatus || vistas[n].status || '').toLowerCase();
  return { n, e };
}).filter((x) => x.e && x.e !== 'open' && x.e !== 'connected');

const malas = salud.filter((s) => ['sin_estrenar', 'callado', 'pico'].indexOf(s.estado) !== -1);

const lineas = [];
if (malas.length) {
  lineas.push('EMPRESAS:');
  for (const m of malas) lineas.push('  - ' + m.empresa + ': ' + m.detalle);
}
if (desconectadas.length) {
  if (lineas.length) lineas.push('');
  lineas.push('WHATSAPP SIN CONECTAR (' + desconectadas.length + ' de ' + Object.keys(vistas).length + '):');
  for (const d of desconectadas) lineas.push('  - ' + d.n + ': ' + d.e);
  lineas.push('');
  lineas.push('Se arregla volviendo a escanear el QR de cada una.');
}

return [{ json: {
  avisar: lineas.length > 0,
  asunto: '[ToqueFlow] ' + (malas.length + desconectadas.length) + ' cosa(s) que revisar',
  cuerpo: lineas.length ? lineas.join('\n') : 'Todo andando.',
  revisadas: Object.keys(vistas).length,
} }];
